-- GENERATED by scripts/build-pipeline-sql.sh from databricks/sql/{00,01,01b,02,03,06,07,05}*.sql. Do not edit by hand.
-- Target: workspace.ux_telemetry, Volume raw_events. Run all statements in order; every step is safe to re-run.

-- ===================================================================== 00_setup.sql
-- Run once. Replace workspace / ux_telemetry / raw_events with your workspace values
-- (Free Edition: use your own catalog, NOT `system`; e.g. catalog=workspace, schema=ux_telemetry, volume=raw_events).
-- Spark/Databricks SQL (not run by the local test harness).
CREATE SCHEMA IF NOT EXISTS workspace.ux_telemetry COMMENT 'UX telemetry research pipeline (bronze/silver/gold)';
CREATE VOLUME IF NOT EXISTS workspace.ux_telemetry.raw_events COMMENT 'Landing zone for raw JSONL telemetry from the uxtelemetry SDK / extension';
-- Upload JSONL files to: /Volumes/workspace/ux_telemetry/raw_events/raw/

-- ===================================================================== 01_bronze_ddl.sql
-- BRONZE: raw events exactly as the SDK sends them (one row per event), plus load metadata. No cleaning here.
-- Explicit schema so downstream SQL never breaks when a field is absent from a given batch.
-- Portable subset: also executed by the local SQLite test harness (STRING -> TEXT there).
-- This is the single list of raw columns: databricks/tools/gen_bronze_load.py writes 01b's read_files schema from it.
-- Chat-study columns (goal .. sel) come from the goals mode: see packages/core/uxtelemetry.js and chatbot.py.
CREATE TABLE IF NOT EXISTS workspace.ux_telemetry.bronze_events (
  t BIGINT, recv_t BIGINT,
  sid STRING, st STRING, app STRING, task STRING, tcat STRING, pid STRING,
  page STRING, path STRING, type STRING, tab BIGINT, frame BIGINT,
  x DOUBLE, y DOUBLE, v DOUBLE, btn BIGINT,
  tag STRING, role STRING, uxid STRING, testid STRING, label STRING, region STRING, dom STRING, action STRING,
  interactive BOOLEAN, ptr BOOLEAN, n BIGINT,
  how STRING, chars BIGINT, words BIGINT, hash STRING, text STRING,
  ctx STRING, combo STRING, del BIGINT,
  dur DOUBLE, pos DOUBLE, ratio DOUBLE, state STRING,
  status STRING, satisfaction BIGINT, answer STRING, name STRING,
  chart STRING, series STRING, prompt STRING,
  w BIGINT, h BIGINT, dpr DOUBLE,
  goal STRING, gcats STRING, turn BIGINT,
  latency_ms BIGINT, behavior STRING, answer_id STRING, correct BOOLEAN, intent STRING, feedback STRING,
  mark_x STRING, mark_y DOUBLE, overlap DOUBLE, sel BOOLEAN, goal_sim DOUBLE, pasted BOOLEAN,
  _source_file STRING, _ingested_at TIMESTAMP
);

-- Sessions to leave out of analysis (restarts, spot checks, test runs). Silver skips every session listed here.
-- Add rows by hand with a reason, e.g. INSERT INTO ... VALUES ('<sid>', 'restart: incomplete');
CREATE TABLE IF NOT EXISTS workspace.ux_telemetry.excluded_sessions (
  session_id STRING, reason STRING
);

-- ===================================================================== 01b_bronze_load.sql
-- GENERATED by databricks/tools/gen_bronze_load.py from 01_bronze_ddl.sql. Do not edit by hand.
-- Rebuild bronze from ALL raw JSONL files in the Volume. Spark/Databricks SQL only.
-- read_files with an EXPLICIT schema: absent fields become NULL, whole numbers parse into DOUBLE columns.
-- CREATE OR REPLACE (not INSERT) so new columns appear on an existing table; the Volume keeps every raw file,
-- so the rebuild loses nothing. _ingested_at is the rebuild time.
CREATE OR REPLACE TABLE workspace.ux_telemetry.bronze_events AS
SELECT t, recv_t, sid, st, app, task, tcat, pid, page, path, type, tab, frame, x, y, v, btn, tag, role, uxid, testid, label, region, dom, action, interactive, ptr, n, how, chars, words, hash, text, ctx, combo, del, dur, pos, ratio, state, status, satisfaction, answer, name, chart, series, prompt, w, h, dpr, goal, gcats, turn, latency_ms, behavior, answer_id, correct, intent, feedback, mark_x, mark_y, overlap, sel, goal_sim, pasted,
       _metadata.file_path AS _source_file, current_timestamp() AS _ingested_at
FROM read_files(
  '/Volumes/workspace/ux_telemetry/raw_events/raw/',
  format => 'json',
  schema => 't BIGINT, recv_t BIGINT, sid STRING, st STRING, app STRING, task STRING, tcat STRING, pid STRING, page STRING, path STRING, type STRING, tab BIGINT, frame BIGINT, x DOUBLE, y DOUBLE, v DOUBLE, btn BIGINT, tag STRING, role STRING, uxid STRING, testid STRING, label STRING, region STRING, dom STRING, action STRING, interactive BOOLEAN, ptr BOOLEAN, n BIGINT, how STRING, chars BIGINT, words BIGINT, hash STRING, text STRING, ctx STRING, combo STRING, del BIGINT, dur DOUBLE, pos DOUBLE, ratio DOUBLE, state STRING, status STRING, satisfaction BIGINT, answer STRING, name STRING, chart STRING, series STRING, prompt STRING, w BIGINT, h BIGINT, dpr DOUBLE, goal STRING, gcats STRING, turn BIGINT, latency_ms BIGINT, behavior STRING, answer_id STRING, correct BOOLEAN, intent STRING, feedback STRING, mark_x STRING, mark_y DOUBLE, overlap DOUBLE, sel BOOLEAN, goal_sim DOUBLE, pasted BOOLEAN'
);

-- ===================================================================== 02_silver.sql
-- SILVER: typed, de-duplicated, human-readable names; trials reconstructed from task_start/outcome events.
-- Portable subset (runs in Databricks SQL and in the local SQLite harness). Keep comments free of semicolons.

-- Events may be re-sent (keepalive retries), so keep one row per (session, time, type, element, position, goal, turn).
-- goal and turn are in the key: two assistant replies for different turns can arrive in the same millisecond.
CREATE OR REPLACE TABLE workspace.ux_telemetry.silver_events AS
SELECT session_id, session_type, app_id, app_version, participant_id, task_id, task_category, page, path, event_type,
       ts_ms, uxid, testid, label, region, action, tag, role, interactive, ptr, x, y, v, n, dur,
       status, satisfaction, answer, chart, series, prompt_text, how, chars, words, prompt_hash, ctx, combo, name,
       goal_id, goal_cats, turn_id, latency_ms, behavior, answer_id, correct, intent, feedback, mark_x, mark_y, overlap,
       had_selection, goal_sim, pasted
FROM (
  SELECT sid AS session_id,
         -- Design revision 2 (2026-11-15): no hover tooltips in v1 (F5), assistant visible in both versions
         -- (B4 retired). Human and agent sessions recorded on the earlier design get their own session type
         -- (human_r1, agent_r1) so they are never pooled with revision-2 data. Simulated data is generated, not recorded.
         -- Live-demo sessions (st=demo, from the /demo console) count as human trials only when all three study goals
         -- were finished (answered or given up); anything less is dropped below, like the partial sessions excluded by hand.
         -- Their participant ids start with DEMO- so they can be told apart or excluded later.
         CASE WHEN st = 'demo' THEN 'human'
              WHEN st IN ('human', 'agent') AND app NOT LIKE '%-r2-%' THEN st || '_r1' ELSE st END AS session_type,
         app AS app_id, substr(app, -2) AS app_version, pid AS participant_id,
         task AS task_id, tcat AS task_category, page, path, type AS event_type,
         CAST(t AS BIGINT) AS ts_ms, uxid, testid, label, region, action, tag, role, interactive, ptr, x, y, v, n, dur,
         status, satisfaction, answer, chart, series, text AS prompt_text, how, chars, words, hash AS prompt_hash, ctx, combo, name,
         goal AS goal_id, gcats AS goal_cats, turn AS turn_id, latency_ms, behavior, answer_id, correct, intent, feedback,
         mark_x, mark_y, overlap, sel AS had_selection, goal_sim, pasted,
         ROW_NUMBER() OVER (
           PARTITION BY sid, t, type, COALESCE(uxid, ''), COALESCE(x, -1), COALESCE(y, -1), COALESCE(goal, ''), COALESCE(turn, -1)
           ORDER BY recv_t
         ) AS rn
  FROM workspace.ux_telemetry.bronze_events
  WHERE sid IS NOT NULL AND t IS NOT NULL
    -- STUDY_SCOPE (2026-11-15): human trials only. A trial = a human (or live-demo) session on the current design that
    -- finished all three study goals (answered or given up). Simulated, agent, earlier-design and unfinished sessions
    -- stay in bronze but never reach silver, so gold, /results, Genie and the designer see only these trials.
    AND sid IN (
          SELECT sid FROM workspace.ux_telemetry.bronze_events
          WHERE st IN ('human', 'demo') AND app LIKE '%-r2-%' AND type = 'goal_outcome' AND goal IN ('G1', 'G2', 'G3')
          GROUP BY sid HAVING COUNT(DISTINCT goal) = 3)  -- STUDY_SCOPE
    AND sid NOT IN (SELECT session_id FROM workspace.ux_telemetry.excluded_sessions WHERE session_id IS NOT NULL)
) d
WHERE rn = 1;

-- One row per (session, task) trial. Assumes each task is attempted once per session.
-- outcome: correct | incorrect | abandoned | no_outcome (the participant left without finishing)
CREATE OR REPLACE TABLE workspace.ux_telemetry.silver_trials AS
SELECT s.session_id, s.session_type, s.app_id, s.app_version, s.participant_id, s.task_id, s.task_category,
       s.start_ms,
       o.end_ms,
       COALESCE(o.outcome, 'no_outcome') AS outcome,
       o.satisfaction,
       o.answer,
       o.duration_ms
FROM (
  SELECT session_id, task_id, task_category, app_id, app_version, participant_id, session_type, MIN(ts_ms) AS start_ms
  FROM workspace.ux_telemetry.silver_events
  WHERE event_type = 'task_start'
  GROUP BY session_id, task_id, task_category, app_id, app_version, participant_id, session_type
) s
LEFT JOIN (
  SELECT session_id, task_id, MAX(ts_ms) AS end_ms, MAX(status) AS outcome,
         MAX(satisfaction) AS satisfaction, MAX(answer) AS answer, MAX(dur) AS duration_ms
  FROM workspace.ux_telemetry.silver_events
  WHERE event_type = 'outcome'
  GROUP BY session_id, task_id
) o ON o.session_id = s.session_id AND o.task_id = s.task_id;

-- ===================================================================== 03_gold.sql
-- GOLD: research metrics. Each metric is a hypothesis about a construct, motivated by the HCI literature triage
-- (docs/literature/signal_paper_matrix.csv). The paper links are title-level and UNVERIFIED until the matrix is filled in.
--   rage / dead clicks      -> frustration or "looks clickable" affordance errors     (struggle/frustration detection papers)
--   hover dwell, hovers     -> attention / reading effort on chart marks              (cursor-as-attention: Huang et al. 2012)
--   idle_ms, first action   -> hesitation / confusion before acting                   (implicit behavioral measures: Rzeszotarski & Kittur 2011)
--   outcome + satisfaction  -> objective success vs self-report; "satisfied but wrong" = over-trust (Human-AI reliance work)
-- Portable subset (Databricks SQL and the local SQLite harness). Study-panel clicks are excluded from friction counts,
-- by region AND by element id: inputs with their own aria-label (the answer boxes) get their own region from the SDK,
-- so the region test alone let them through (seen in the first human session: goal-answer showed up as friction).

-- Per-trial friction metrics: behavior events that fall inside the trial's time window.
CREATE OR REPLACE TABLE workspace.ux_telemetry.gold_trial_metrics AS
SELECT t.session_id, t.session_type, t.app_id, t.app_version, t.participant_id, t.task_id, t.task_category,
       t.outcome, t.satisfaction, t.duration_ms,
       SUM(CASE WHEN e.event_type = 'click' THEN 1 ELSE 0 END) AS n_clicks,
       SUM(CASE WHEN e.event_type = 'rage_click' THEN 1 ELSE 0 END) AS n_rage_clicks,
       SUM(CASE WHEN e.event_type = 'click' AND e.ptr = TRUE AND e.interactive = FALSE THEN 1 ELSE 0 END) AS n_dead_clicks,
       SUM(CASE WHEN e.event_type = 'chart_hover' THEN 1 ELSE 0 END) AS n_chart_hovers,
       COALESCE(SUM(CASE WHEN e.event_type = 'chart_hover' THEN e.dur END), 0) AS chart_hover_ms,
       SUM(CASE WHEN e.event_type = 'chart_legend_click' THEN 1 ELSE 0 END) AS n_legend_clicks,
       COALESCE(SUM(CASE WHEN e.event_type = 'idle_end' THEN e.dur END), 0) AS idle_ms,
       SUM(CASE WHEN e.event_type = 'prompt_submit' THEN 1 ELSE 0 END) AS n_prompts,
       MIN(CASE WHEN e.event_type IN ('click', 'key', 'chart_hover', 'chart_click') THEN e.ts_ms END) - t.start_ms AS first_action_ms
FROM workspace.ux_telemetry.silver_trials t
LEFT JOIN workspace.ux_telemetry.silver_events e
  ON e.session_id = t.session_id
 AND e.ts_ms >= t.start_ms
 AND e.ts_ms <= COALESCE(t.end_ms, 9223372036854775807)
 AND COALESCE(e.region, '') <> 'aside:study-panel'
 AND COALESCE(e.uxid, '') NOT LIKE 'task-%' AND COALESCE(e.uxid, '') NOT LIKE 'goal-%' AND COALESCE(e.uxid, '') NOT LIKE 'sat-%' AND COALESCE(e.uxid, '') NOT LIKE 'gsat-%' AND COALESCE(e.uxid, '') NOT LIKE 'consent-%'
GROUP BY t.session_id, t.session_type, t.app_id, t.app_version, t.participant_id, t.task_id, t.task_category,
         t.outcome, t.satisfaction, t.duration_ms, t.start_ms;

-- Per session type x task x design version: outcomes and friction. overtrust_rate = share of WRONG answers rated satisfied (4-5).
-- session_type is a grouping key so simulated (bot) trials are never averaged together with human ones.
CREATE OR REPLACE TABLE workspace.ux_telemetry.gold_task_summary AS
SELECT session_type, app_version, task_id, task_category,
       COUNT(*) AS n_trials,
       AVG(CASE WHEN outcome = 'correct' THEN 1.0 ELSE 0.0 END) AS success_rate,
       AVG(CASE WHEN outcome = 'abandoned' THEN 1.0 ELSE 0.0 END) AS abandon_rate,
       AVG(satisfaction) AS avg_satisfaction,
       AVG(duration_ms) AS avg_duration_ms,
       AVG(n_rage_clicks) AS avg_rage_clicks,
       AVG(n_dead_clicks) AS avg_dead_clicks,
       AVG(n_chart_hovers) AS avg_chart_hovers,
       AVG(chart_hover_ms) AS avg_chart_hover_ms,
       AVG(n_legend_clicks) AS avg_legend_clicks,
       AVG(idle_ms) AS avg_idle_ms,
       AVG(first_action_ms) AS avg_first_action_ms,
       SUM(CASE WHEN outcome = 'incorrect' AND satisfaction >= 4 THEN 1.0 ELSE 0.0 END)
         / NULLIF(SUM(CASE WHEN outcome = 'incorrect' THEN 1.0 ELSE 0.0 END), 0) AS overtrust_rate
FROM workspace.ux_telemetry.gold_trial_metrics
GROUP BY session_type, app_version, task_id, task_category;

-- Which UI elements attract rage / dead clicks (excludes the study panel). Ranks candidate affordance problems.
CREATE OR REPLACE TABLE workspace.ux_telemetry.gold_element_friction AS
SELECT session_type, app_version, uxid,
       SUM(CASE WHEN event_type = 'click' THEN 1 ELSE 0 END) AS n_clicks,
       SUM(CASE WHEN event_type = 'rage_click' THEN 1 ELSE 0 END) AS n_rage_clicks,
       SUM(CASE WHEN event_type = 'click' AND ptr = TRUE AND interactive = FALSE THEN 1 ELSE 0 END) AS n_dead_clicks,
       COUNT(DISTINCT session_id) AS n_sessions,
       SUM(CASE WHEN event_type = 'rage_click' THEN 1.0 ELSE 0.0 END)
         / NULLIF(SUM(CASE WHEN event_type = 'click' THEN 1.0 ELSE 0.0 END), 0) AS rage_per_click
FROM workspace.ux_telemetry.silver_events
WHERE uxid IS NOT NULL AND event_type IN ('click', 'rage_click') AND COALESCE(region, '') <> 'aside:study-panel'
  AND COALESCE(uxid, '') NOT LIKE 'task-%' AND COALESCE(uxid, '') NOT LIKE 'goal-%' AND COALESCE(uxid, '') NOT LIKE 'sat-%' AND COALESCE(uxid, '') NOT LIKE 'gsat-%' AND COALESCE(uxid, '') NOT LIKE 'consent-%'
GROUP BY session_type, app_version, uxid;

-- Before/after for the iteration loop: v1 (current UI) vs v2 (proposed change), per session type and task.
CREATE OR REPLACE TABLE workspace.ux_telemetry.gold_version_comparison AS
SELECT a.session_type, a.task_id, a.task_category,
       a.success_rate AS success_rate_v1, b.success_rate AS success_rate_v2, b.success_rate - a.success_rate AS success_delta,
       a.abandon_rate AS abandon_rate_v1, b.abandon_rate AS abandon_rate_v2,
       a.avg_duration_ms AS avg_duration_ms_v1, b.avg_duration_ms AS avg_duration_ms_v2,
       a.avg_rage_clicks AS avg_rage_clicks_v1, b.avg_rage_clicks AS avg_rage_clicks_v2,
       a.overtrust_rate AS overtrust_rate_v1, b.overtrust_rate AS overtrust_rate_v2,
       a.n_trials AS n_trials_v1, b.n_trials AS n_trials_v2
FROM workspace.ux_telemetry.gold_task_summary a
JOIN workspace.ux_telemetry.gold_task_summary b ON a.task_id = b.task_id AND a.session_type = b.session_type
WHERE a.app_version = 'v1' AND b.app_version = 'v2';

-- ===================================================================== 06_silver_chat.sql
-- SILVER (chat study, mode=goals): goals and assistant turns, rebuilt from silver_events.
-- Portable subset (Databricks SQL and the local SQLite harness). Keep comments free of semicolons.
-- silver_trials (scripted tasks) is untouched: a goal is not a task, and one goal has many turns.
-- correct / accepted / had_selection are 1 / 0 integers here (NULL correct = the assistant did not answer the question,
-- e.g. it asked which borough, or no reply arrived).
-- Turns outside a goal (the chat used outside study mode) have goal_id NULL and are not included.

-- One row per (session, goal). outcome: correct | incorrect | abandoned | no_outcome (left without finishing).
-- final_turn = the assistant turn whose answer the participant submitted (NULL if they typed their own answer).
CREATE OR REPLACE TABLE workspace.ux_telemetry.silver_goals AS
SELECT s.session_id, s.session_type, s.app_id, s.app_version, s.participant_id, s.goal_id, s.goal_cats,
       s.start_ms,
       o.end_ms,
       COALESCE(o.outcome, 'no_outcome') AS outcome,
       o.satisfaction,
       o.final_answer,
       o.final_turn,
       o.duration_ms
FROM (
  SELECT session_id, session_type, app_id, app_version, participant_id, goal_id, MAX(goal_cats) AS goal_cats,
         MIN(ts_ms) AS start_ms
  FROM workspace.ux_telemetry.silver_events
  WHERE event_type = 'goal_start' AND goal_id IS NOT NULL
  GROUP BY session_id, session_type, app_id, app_version, participant_id, goal_id
) s
LEFT JOIN (
  SELECT session_id, goal_id, MAX(ts_ms) AS end_ms, MAX(status) AS outcome, MAX(satisfaction) AS satisfaction,
         MAX(answer) AS final_answer, MAX(turn_id) AS final_turn, MAX(dur) AS duration_ms
  FROM workspace.ux_telemetry.silver_events
  WHERE event_type = 'goal_outcome'
  GROUP BY session_id, goal_id
) o ON o.session_id = s.session_id AND o.goal_id = s.goal_id;

-- One row per prompt / response pair, keyed by (session, goal, turn).
-- overlap = token overlap of this prompt with the previous prompt in the same goal, computed in the browser
-- (content tokens = lowercase alphanumerics minus stopwords, overlap coefficient |A and B| / min(|A|, |B|)), so the
-- reformulation metric works without storing prompt text. prompt_text is only present with the participant's consent.
-- goal_sim = Jaccard similarity of the prompt with the goal text (also computed in the browser) and pasted = something
-- was pasted into the chat box before this prompt: together they flag a pasted goal (see gold_turn_metrics).
CREATE OR REPLACE TABLE workspace.ux_telemetry.silver_turns AS
SELECT p.session_id, p.session_type, p.app_id, p.app_version, p.participant_id, p.goal_id, p.turn_id,
       p.prompt_ms, r.response_ms, r.latency_ms,
       p.prompt_hash, p.prompt_text, p.chars, p.words, p.overlap, p.had_selection, p.goal_sim, p.pasted,
       r.intent, r.behavior, r.answer_id, r.correct, r.bot_answer, r.mark_x,
       CASE WHEN COALESCE(f.n_accept_copy, 0) > 0 THEN 1 ELSE 0 END AS accepted,
       COALESCE(f.n_thumbs_up, 0) AS n_thumbs_up,
       COALESCE(f.n_thumbs_down, 0) AS n_thumbs_down
FROM (
  SELECT session_id, session_type, app_id, app_version, participant_id, goal_id, turn_id,
         MIN(ts_ms) AS prompt_ms, MAX(prompt_hash) AS prompt_hash, MAX(prompt_text) AS prompt_text,
         MAX(chars) AS chars, MAX(words) AS words, MAX(overlap) AS overlap,
         MAX(CASE WHEN had_selection = TRUE THEN 1 ELSE 0 END) AS had_selection,
         MAX(goal_sim) AS goal_sim,
         MAX(CASE WHEN pasted = TRUE THEN 1 ELSE 0 END) AS pasted
  FROM workspace.ux_telemetry.silver_events
  WHERE event_type = 'prompt_submit' AND goal_id IS NOT NULL AND turn_id IS NOT NULL
  GROUP BY session_id, session_type, app_id, app_version, participant_id, goal_id, turn_id
) p
LEFT JOIN (
  SELECT session_id, goal_id, turn_id, MIN(ts_ms) AS response_ms, MAX(latency_ms) AS latency_ms,
         MAX(intent) AS intent, MAX(behavior) AS behavior, MAX(answer_id) AS answer_id,
         MAX(CASE WHEN correct = TRUE THEN 1 WHEN correct = FALSE THEN 0 END) AS correct,
         MAX(answer) AS bot_answer, MAX(mark_x) AS mark_x
  FROM workspace.ux_telemetry.silver_events
  WHERE event_type = 'assistant_response'
  GROUP BY session_id, goal_id, turn_id
) r ON r.session_id = p.session_id AND r.goal_id = p.goal_id AND r.turn_id = p.turn_id
LEFT JOIN (
  SELECT session_id, goal_id, turn_id,
         SUM(CASE WHEN feedback IN ('accept', 'copy') THEN 1 ELSE 0 END) AS n_accept_copy,
         SUM(CASE WHEN feedback = 'thumbs_up' THEN 1 ELSE 0 END) AS n_thumbs_up,
         SUM(CASE WHEN feedback = 'thumbs_down' THEN 1 ELSE 0 END) AS n_thumbs_down
  FROM workspace.ux_telemetry.silver_events
  WHERE event_type = 'answer_feedback'
  GROUP BY session_id, goal_id, turn_id
) f ON f.session_id = p.session_id AND f.goal_id = p.goal_id AND f.turn_id = p.turn_id;

-- ===================================================================== 07_gold_chat.sql
-- GOLD (chat study): turn, goal and planted-behavior metrics. Portable subset (Databricks SQL + local SQLite harness).
-- Keep comments free of semicolons. Every table keeps session_type so simulated and human rows are never mixed.
-- The rules below are proxies for constructs, not measurements of them, and samples are small.
--
--   reformulated    the NEXT prompt in the same goal comes within 60 s of this prompt AND its token overlap with this
--                   prompt is >= 0.6 (overlap = |A and B| / min(|A|, |B|) over content tokens, computed in the browser)
--   repair_attempt  this turn failed (wrong answer, or no answer to the question) and the participant sent another
--                   prompt in the same goal within 60 s of the reply, whatever the overlap
--   verified        a chart interaction (hover, click, legend, zoom, selection, borough filter change) within 10 s
--                   after the assistant's reply
--   failed turn     a reply arrived and correct = 0 or correct IS NULL (the stub did not answer the question)
--   relied_on_wrong a wrong reply (correct = 0) was accepted or copied, or its turn is the one whose answer was
--                   submitted as the final answer
--   overtrust       relied_on_wrong AND satisfaction 4-5 AND the final answer is not correct (a participant who
--                   accepted a wrong reply but then submitted the right answer is not counted)
--   dropoff         the goal ended abandoned or with no outcome after k >= 1 failed turns (k is reported)
--   pasted_goal     the participant pasted into the chat box and the prompt's Jaccard similarity with the goal text is
--                   >= 0.8: the goal was handed to the assistant, not phrased by the participant. Metrics named
--                   *_excl_pasted repeat the main metric without these turns (or without goals whose first prompt was one).

-- One row per turn with the flags above.
CREATE OR REPLACE TABLE workspace.ux_telemetry.gold_turn_metrics AS
SELECT t.session_id, t.session_type, t.app_id, t.app_version, t.participant_id, t.goal_id, t.turn_id,
       t.prompt_ms, t.response_ms, t.latency_ms, t.intent, t.behavior, t.answer_id, t.correct, t.accepted,
       t.had_selection, t.overlap, t.chars, t.words, t.goal_sim, t.pasted,
       CASE WHEN t.pasted = 1 AND t.goal_sim >= 0.8 THEN 1 ELSE 0 END AS pasted_goal,
       CASE WHEN t.response_ms IS NOT NULL AND (t.correct = 0 OR t.correct IS NULL) THEN 1 ELSE 0 END AS failed,
       CASE WHEN t.next_prompt_ms IS NOT NULL AND t.next_prompt_ms - t.prompt_ms <= 60000
                 AND t.next_overlap >= 0.6 THEN 1 ELSE 0 END AS reformulated,
       CASE WHEN t.response_ms IS NOT NULL AND (t.correct = 0 OR t.correct IS NULL)
                 AND t.next_prompt_ms IS NOT NULL AND t.next_prompt_ms - t.response_ms <= 60000 THEN 1 ELSE 0 END AS repair_attempt,
       CASE WHEN COALESCE(v.n_chart_after, 0) > 0 THEN 1 ELSE 0 END AS verified
FROM (
  SELECT s.*,
         LEAD(s.prompt_ms) OVER (PARTITION BY s.session_id, s.goal_id ORDER BY s.turn_id) AS next_prompt_ms,
         LEAD(s.overlap) OVER (PARTITION BY s.session_id, s.goal_id ORDER BY s.turn_id) AS next_overlap
  FROM workspace.ux_telemetry.silver_turns s
) t
LEFT JOIN (
  SELECT st.session_id, st.goal_id, st.turn_id, COUNT(*) AS n_chart_after
  FROM workspace.ux_telemetry.silver_turns st
  JOIN workspace.ux_telemetry.silver_events e
    ON e.session_id = st.session_id
   AND e.ts_ms > st.response_ms AND e.ts_ms <= st.response_ms + 10000
   AND (e.event_type IN ('chart_hover', 'chart_click', 'chart_legend_click', 'chart_legend_dblclick', 'chart_relayout',
                         'chart_select', 'selection')
        OR (e.event_type = 'custom' AND e.name = 'filter_change'))
  GROUP BY st.session_id, st.goal_id, st.turn_id
) v ON v.session_id = t.session_id AND v.goal_id = t.goal_id AND v.turn_id = t.turn_id;

-- One row per goal attempt with turn counts, over-trust and drop-off flags.
CREATE OR REPLACE TABLE workspace.ux_telemetry.gold_goal_metrics AS
SELECT g.session_id, g.session_type, g.app_id, g.app_version, g.participant_id, g.goal_id, g.goal_cats,
       g.outcome, g.satisfaction, g.duration_ms, g.final_turn,
       COALESCE(a.n_turns, 0) AS n_turns,
       COALESCE(a.n_failed_turns, 0) AS n_failed_turns,
       COALESCE(a.n_reformulations, 0) AS n_reformulations,
       COALESCE(a.n_verified, 0) AS n_verified_turns,
       COALESCE(a.n_pasted_goal, 0) AS n_pasted_goal_turns,
       COALESCE(a.first_pasted_goal, 0) AS first_prompt_pasted_goal,
       a.first_prompt_ms - g.start_ms AS time_to_first_prompt_ms,
       CASE WHEN COALESCE(a.n_wrong, 0) > 0 THEN 1 ELSE 0 END AS wrong_answer_shown,
       COALESCE(w.relied_on_wrong, 0) AS relied_on_wrong,
       CASE WHEN COALESCE(w.relied_on_wrong, 0) = 1 AND g.satisfaction >= 4 AND g.outcome <> 'correct' THEN 1 ELSE 0 END AS overtrust,
       CASE WHEN g.outcome IN ('abandoned', 'no_outcome') AND COALESCE(a.n_failed_turns, 0) >= 1 THEN 1 ELSE 0 END AS dropoff_after_failure,
       COALESCE(c.n_chart_hovers, 0) AS n_chart_hovers,
       COALESCE(c.chart_hover_ms, 0) AS chart_hover_ms,
       COALESCE(c.n_dead_clicks, 0) AS n_dead_clicks,
       COALESCE(c.n_rage_clicks, 0) AS n_rage_clicks
FROM workspace.ux_telemetry.silver_goals g
LEFT JOIN (
  SELECT session_id, goal_id, COUNT(*) AS n_turns, SUM(failed) AS n_failed_turns, SUM(reformulated) AS n_reformulations,
         SUM(verified) AS n_verified, MIN(prompt_ms) AS first_prompt_ms, SUM(pasted_goal) AS n_pasted_goal,
         MAX(CASE WHEN turn_id = 1 THEN pasted_goal ELSE 0 END) AS first_pasted_goal,
         SUM(CASE WHEN correct = 0 THEN 1 ELSE 0 END) AS n_wrong
  FROM workspace.ux_telemetry.gold_turn_metrics
  GROUP BY session_id, goal_id
) a ON a.session_id = g.session_id AND a.goal_id = g.goal_id
LEFT JOIN (
  SELECT t.session_id, t.goal_id,
         MAX(CASE WHEN t.correct = 0 AND (t.accepted = 1 OR t.turn_id = g2.final_turn) THEN 1 ELSE 0 END) AS relied_on_wrong
  FROM workspace.ux_telemetry.gold_turn_metrics t
  JOIN workspace.ux_telemetry.silver_goals g2 ON g2.session_id = t.session_id AND g2.goal_id = t.goal_id
  GROUP BY t.session_id, t.goal_id
) w ON w.session_id = g.session_id AND w.goal_id = g.goal_id
-- page activity while the goal was open (study panel excluded): chart hovers, hover time, dead and rage clicks
LEFT JOIN (
  SELECT session_id, goal_id,
         SUM(CASE WHEN event_type = 'chart_hover' THEN 1 ELSE 0 END) AS n_chart_hovers,
         COALESCE(SUM(CASE WHEN event_type = 'chart_hover' THEN dur END), 0) AS chart_hover_ms,
         SUM(CASE WHEN event_type = 'click' AND ptr = TRUE AND interactive = FALSE THEN 1 ELSE 0 END) AS n_dead_clicks,
         SUM(CASE WHEN event_type = 'rage_click' THEN 1 ELSE 0 END) AS n_rage_clicks
  FROM workspace.ux_telemetry.silver_events
  WHERE goal_id IS NOT NULL AND COALESCE(region, '') <> 'aside:study-panel'
    AND COALESCE(uxid, '') NOT LIKE 'task-%' AND COALESCE(uxid, '') NOT LIKE 'goal-%' AND COALESCE(uxid, '') NOT LIKE 'gsat-%' AND COALESCE(uxid, '') NOT LIKE 'consent-%'
  GROUP BY session_id, goal_id
) c ON c.session_id = g.session_id AND c.goal_id = g.goal_id;

-- Per session type x design version x goal.
CREATE OR REPLACE TABLE workspace.ux_telemetry.gold_goal_summary AS
SELECT session_type, app_version, goal_id, MAX(goal_cats) AS goal_cats,
       COUNT(*) AS n_goals,
       AVG(CASE WHEN outcome = 'correct' THEN 1.0 ELSE 0.0 END) AS success_rate,
       AVG(CASE WHEN outcome = 'abandoned' THEN 1.0 ELSE 0.0 END) AS abandon_rate,
       AVG(CASE WHEN outcome = 'no_outcome' THEN 1.0 ELSE 0.0 END) AS no_outcome_rate,
       AVG(n_turns * 1.0) AS avg_turns,
       AVG(CASE WHEN outcome = 'correct' THEN n_turns * 1.0 END) AS avg_turns_to_success,
       AVG(time_to_first_prompt_ms * 1.0) AS avg_time_to_first_prompt_ms,
       AVG(duration_ms * 1.0) AS avg_duration_ms,
       AVG(satisfaction * 1.0) AS avg_satisfaction,
       SUM(wrong_answer_shown) AS n_wrong_answer_shown,
       SUM(overtrust) * 1.0 / NULLIF(SUM(wrong_answer_shown), 0) AS overtrust_rate,
       AVG(dropoff_after_failure * 1.0) AS dropoff_rate,
       AVG(CASE WHEN dropoff_after_failure = 1 THEN n_failed_turns * 1.0 END) AS avg_failed_turns_at_dropoff,
       AVG(n_chart_hovers * 1.0) AS avg_chart_hovers,
       AVG(chart_hover_ms * 1.0) AS avg_chart_hover_ms,
       AVG(n_dead_clicks * 1.0) AS avg_dead_clicks,
       AVG(n_rage_clicks * 1.0) AS avg_rage_clicks,
       SUM(first_prompt_pasted_goal) AS n_goals_pasted_goal,
       AVG(CASE WHEN first_prompt_pasted_goal = 0 THEN (CASE WHEN outcome = 'correct' THEN 1.0 ELSE 0.0 END) END) AS success_rate_excl_pasted,
       AVG(CASE WHEN first_prompt_pasted_goal = 0 THEN time_to_first_prompt_ms * 1.0 END) AS avg_time_to_first_prompt_ms_excl_pasted
FROM workspace.ux_telemetry.gold_goal_metrics
GROUP BY session_type, app_version, goal_id;

-- Per planted assistant behavior (B1-B5) x design version: v1 = flawed, v2 = fixed.
-- Turn metrics for B1, B2, B3, B5 come from the turns where the behavior fired. Goal metrics come from the goals that
-- contain such a turn. B4 (hidden chat entry point) is a page behavior: its row reports time from the first goal to the
-- first chat_open per session (0 if the chat was already open) and the share of sessions that never opened it.
CREATE OR REPLACE TABLE workspace.ux_telemetry.gold_bot_behavior AS
SELECT t.session_type, t.behavior, t.app_version, t.n_turns, g.n_goals, NULL AS n_sessions,
       t.wrong_answer_rate, t.reformulation_rate, t.repair_rate, t.verification_rate, t.avg_latency_ms,
       g.goal_success_rate, g.goal_abandon_rate, g.overtrust_rate,
       NULL AS avg_ms_to_chat_open, NULL AS never_opened_rate,
       t.pasted_goal_share, t.wrong_answer_rate_excl_pasted, t.reformulation_rate_excl_pasted, g.goal_abandon_rate_excl_pasted
FROM (
  SELECT session_type, behavior, app_version, COUNT(*) AS n_turns,
         AVG(CASE WHEN correct = 0 THEN 1.0 ELSE 0.0 END) AS wrong_answer_rate,
         AVG(reformulated * 1.0) AS reformulation_rate,
         AVG(repair_attempt * 1.0) AS repair_rate,
         AVG(verified * 1.0) AS verification_rate,
         AVG(latency_ms * 1.0) AS avg_latency_ms,
         AVG(pasted_goal * 1.0) AS pasted_goal_share,
         AVG(CASE WHEN pasted_goal = 0 THEN (CASE WHEN correct = 0 THEN 1.0 ELSE 0.0 END) END) AS wrong_answer_rate_excl_pasted,
         AVG(CASE WHEN pasted_goal = 0 THEN reformulated * 1.0 END) AS reformulation_rate_excl_pasted
  FROM workspace.ux_telemetry.gold_turn_metrics
  WHERE behavior IS NOT NULL
  GROUP BY session_type, behavior, app_version
) t
JOIN (
  SELECT b.session_type, b.behavior, b.app_version, COUNT(*) AS n_goals,
         AVG(CASE WHEN m.outcome = 'correct' THEN 1.0 ELSE 0.0 END) AS goal_success_rate,
         AVG(CASE WHEN m.outcome IN ('abandoned', 'no_outcome') THEN 1.0 ELSE 0.0 END) AS goal_abandon_rate,
         SUM(m.overtrust) * 1.0 / NULLIF(SUM(m.wrong_answer_shown), 0) AS overtrust_rate,
         AVG(CASE WHEN m.first_prompt_pasted_goal = 0 THEN (CASE WHEN m.outcome IN ('abandoned', 'no_outcome') THEN 1.0 ELSE 0.0 END) END) AS goal_abandon_rate_excl_pasted
  FROM (SELECT DISTINCT session_type, behavior, app_version, session_id, goal_id
        FROM workspace.ux_telemetry.gold_turn_metrics WHERE behavior IS NOT NULL) b
  JOIN workspace.ux_telemetry.gold_goal_metrics m ON m.session_id = b.session_id AND m.goal_id = b.goal_id
  GROUP BY b.session_type, b.behavior, b.app_version
) g ON g.session_type = t.session_type AND g.behavior = t.behavior AND g.app_version = t.app_version
UNION ALL
SELECT s.session_type, 'B4' AS behavior, s.app_version, NULL AS n_turns, NULL AS n_goals, COUNT(*) AS n_sessions,
       NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
       AVG(CASE WHEN s.first_open_ms IS NULL THEN NULL
                WHEN s.first_open_ms < s.first_goal_ms THEN 0.0
                ELSE (s.first_open_ms - s.first_goal_ms) * 1.0 END) AS avg_ms_to_chat_open,
       AVG(CASE WHEN s.first_open_ms IS NULL THEN 1.0 ELSE 0.0 END) AS never_opened_rate,
       NULL, NULL, NULL, NULL
FROM (
  SELECT session_id, session_type, app_version,
         MIN(CASE WHEN event_type = 'goal_start' THEN ts_ms END) AS first_goal_ms,
         MIN(CASE WHEN event_type = 'chat_open' THEN ts_ms END) AS first_open_ms
  FROM workspace.ux_telemetry.silver_events
  GROUP BY session_id, session_type, app_version
  HAVING MIN(CASE WHEN event_type = 'goal_start' THEN ts_ms END) IS NOT NULL
) s
GROUP BY s.session_type, s.app_version;

-- ===================================================================== 05_comments.sql
-- Unity Catalog comments carry the research context to Genie (and to anyone browsing the catalog).
-- Genie reads table/column descriptions, so definitions written here steer how it answers.
-- Spark/Databricks SQL only. UNTESTED (no workspace access from the sandbox).

COMMENT ON TABLE workspace.ux_telemetry.gold_trial_metrics IS
  'One row per (session, task) trial with friction metrics. Behavior counts exclude the study panel. session_type: human = real participants, simulated = generated from assumed rates (test data), agent = bots using the real dashboard with one fixed strategy for v1 and v2. Only human is real users.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.outcome IS
  'Objective result: correct, incorrect, abandoned (clicked I give up), or no_outcome (left without finishing). Success = correct.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.satisfaction IS
  'Self-reported 1-5 (5 = very satisfied) asked after answering. NULL when abandoned. Self-report, so compare with outcome rather than trusting it alone.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.task_category IS
  'Amar, Eagan and Stasko (2005) low-level analytic task the trial exercises: retrieve_value, filter, compute_derived_value, find_extremum, sort, determine_range, characterize_distribution, find_anomalies, cluster, correlate.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.n_rage_clicks IS
  'Bursts of 3+ clicks within 700 ms in the same spot. Proxy for frustration or a control that looks usable but does not respond.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.n_dead_clicks IS
  'Clicks on non-interactive elements that show a pointer cursor ("looks clickable but is not"). Affordance problem signal.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.idle_ms IS
  'Total time in pauses of 30 s or more with no input during the trial. Proxy for hesitation or confusion, not proof.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.chart_hover_ms IS
  'Total time hovering chart marks. Cursor-as-attention proxy: cursor position only loosely tracks gaze.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.first_action_ms IS
  'Milliseconds from trial start to the first click, key press, or chart interaction outside the study panel.';

COMMENT ON TABLE workspace.ux_telemetry.gold_task_summary IS
  'Aggregates of gold_trial_metrics per session_type (human or simulated, never mixed), design version (v1 = current UI, v2 = proposed change) and task. success_rate and abandon_rate are 0-1 fractions.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_task_summary.overtrust_rate IS
  'Share of INCORRECT answers that were rated 4-5 for satisfaction ("satisfied but wrong"). NULL when no incorrect answers.';

COMMENT ON COLUMN workspace.ux_telemetry.gold_task_summary.avg_chart_hover_ms IS
  'Average time per trial spent hovering chart marks (from the chart adapter; recorded whether or not a tooltip is shown). High hover time with low success suggests people are trying to read values off the chart.';

COMMENT ON TABLE workspace.ux_telemetry.gold_element_friction IS
  'Rage and dead clicks per session_type, UI element (uxid) and design version. Highest rage_per_click flags elements with affordance problems.';

COMMENT ON TABLE workspace.ux_telemetry.gold_version_comparison IS
  'v1 vs v2 per session_type and task (human and simulated are separate rows): success_delta = success_rate_v2 - success_rate_v1. Used to judge whether a proposed UI change helped. Small samples: treat as descriptive.';

-- ---------------------------------------------------------------- chat study (06_silver_chat.sql, 07_gold_chat.sql)
COMMENT ON TABLE workspace.ux_telemetry.silver_goals IS
  'One row per (session, goal) in the chat-assistant study. A goal is an open-ended need (e.g. the Bronx average fare) worked on with the dashboard assistant. outcome: correct | incorrect | abandoned | no_outcome. final_turn = the assistant turn whose answer was submitted (NULL if typed by the participant).';
COMMENT ON TABLE workspace.ux_telemetry.silver_turns IS
  'One row per prompt/response pair (session, goal, turn). correct is 1/0 testbed ground truth from the stub assistant (NULL = it did not answer the question). prompt_text only with participant consent. overlap = token overlap with the previous prompt of the goal, computed in the browser.';
COMMENT ON TABLE workspace.ux_telemetry.gold_turn_metrics IS
  'Per assistant turn: failed, reformulated, repair_attempt and verified flags. Proxies, not measurements: see the column comments for the exact rules. session_type=simulated rows are bot-generated.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_turn_metrics.reformulated IS
  '1 if the next prompt in the same goal came within 60 s of this prompt and its token overlap with this prompt is >= 0.6 (overlap coefficient over lowercase content tokens, stopwords removed).';
COMMENT ON COLUMN workspace.ux_telemetry.gold_turn_metrics.repair_attempt IS
  '1 if this turn failed (wrong reply, or no answer to the question) and another prompt in the same goal followed within 60 s of the reply, whatever its overlap.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_turn_metrics.verified IS
  '1 if the participant interacted with a chart (hover, click, legend, zoom, point selection) or changed the borough filter within 10 s after the reply.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_turn_metrics.behavior IS
  'Planted assistant behavior that fired on this turn: B1 confident wrong percent, B2 borough ignored, B3 slow reply, B5 chart selection ignored (v1 = flawed, v2 = fixed). NULL = no planted behavior.';
COMMENT ON TABLE workspace.ux_telemetry.gold_goal_metrics IS
  'Per goal attempt: turns, failed turns, over-trust and drop-off flags. overtrust = a wrong assistant answer was accepted, copied or submitted, satisfaction 4-5, and the final answer is not correct. dropoff_after_failure = abandoned or no outcome after at least one failed turn.';
COMMENT ON TABLE workspace.ux_telemetry.gold_goal_summary IS
  'Per session_type, design version and goal: success, abandonment, turns, time to first prompt, over-trust (share of goals that showed a wrong answer) and drop-off (avg_failed_turns_at_dropoff = k). Small samples: descriptive only.';
COMMENT ON TABLE workspace.ux_telemetry.gold_bot_behavior IS
  'Per planted assistant behavior (B1-B5) and design version (v1 flawed, v2 fixed): wrong-answer, reformulation, repair and verification rates, latency, and outcomes of the goals where the behavior fired. B4 (chat entry point hidden in v1) reports avg_ms_to_chat_open and never_opened_rate per session; it was retired in design revision 2 (assistant open in both versions), so revision-2 rows should show no v1/v2 difference.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_turn_metrics.pasted_goal IS
  '1 if the participant pasted into the chat box and the prompt has Jaccard similarity >= 0.8 with the goal text (the goal was handed to the assistant rather than phrased by the participant). Columns ending in _excl_pasted in the other chat tables repeat a metric without these.';
